mapper.sql:
from announce a
left join announce_goods_detail g on g.announce_id = a.id
left join announce_job j on j.announce_id = a.id
left join announce_event e on e.announce_id = a.id
where a.deleted = 0
and a.kind = #{kind}
and a.`status` = #{status}
and a.seller_id = #{sellerId}
and a.region_id = #{regionId}

  and a.category_id in
  #{c}

and g.brand_id = #{brandId}
and g.sale_type = #{saleType}
and (a.title like concat('%', #{keywords}, '%') or a.keywords like concat('%', #{keywords}, '%'))
